}

{
    "id": "https://schema.management.azure.com/schemas/2015-08-01/Microsoft.Storage.json#",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Microsoft.Storage",
    "description": "Microsoft Storage Resource Types",
    "resourceDefinitions": {
        "storageAccounts": {
            "type": "object",
            "properties": {
                "type": {
                    "enum": [
                        "Microsoft.Storage/storageAccounts"
                    ]
                },
                "apiVersion": {
                    "enum": [
                        "2015-05-01-preview",
                        "2015-06-15"
                    ]
                },
                "properties": {
                    "type": "object",
                    "properties": {
                        "accountType": {
                            "type": "string",
                            "minLength": 1,
                            "description": "Microsoft.Storage/storageAccounts: The type of this account."
                        }
                    },
                    "required": [
                        "accountType"
                    ]
                }
            },
            "required": [
                "type",
                "apiVersion",
                "properties",
                "location"
            ],
            "description": "Microsoft.Storage/storageAccounts"
        }
    },
    "properties": {
        "resourceDefinitions.storageAccounts": {
            "$ref": "#/resourceDefinitions/storageAccounts"
        }
    },
    "required": [
        "resourceDefinitions.storageAccounts"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "id": "http://judkins.house/apis/k2/v1/kubeDns.json",
    "$$target": "kubeDns.json",
    "title": "Kubernetes DNS Configurations",
    "description": "Describes the configuration of DNS for the Kubernetes cluster.",
    "properties": {
        "cluster_ip": {
            "description": "This should be the same as the IP set in the deployment.clusters[x].dns in the main configuration file.",
            "type": "string"
        },
        "dns_domain": {
            "description": "This should be the same as the domain set in deployment.clusters[x].domain in the main configuration file.",
            "type": "string"
        },
        "namespace": {
            "description": "Kubernetes is expecting DNS to be in kube-system.",
            "type": "string"
        }
    },
    "required": [
        "cluster_ip",
        "dns_domain"
    ],
    "additionalProperties": false,
    "type": "object"
}

